export type AppLanguage = 'en' | 'ar';

export function currentLanguage(): AppLanguage {
  if (typeof document !== 'undefined' && document.documentElement.lang === 'ar') return 'ar';
  try {
    const saved = localStorage.getItem('rentora.language');
    if (saved && JSON.parse(saved) === 'ar') return 'ar';
  } catch { /* use the default language */ }
  return 'en';
}

export function localeFor(language: AppLanguage = currentLanguage()): string {
  return language === 'ar' ? 'ar-SY-u-nu-arab' : 'en-US-u-nu-latn';
}

export function formatNumber(value: number, options: Intl.NumberFormatOptions = {}, language: AppLanguage = currentLanguage()): string {
  return new Intl.NumberFormat(localeFor(language), options).format(value);
}

export function formatCurrency(value: number, currency = 'USD', language: AppLanguage = currentLanguage()): string {
  if (currency === 'SYP') {
    const number = formatNumber(value, { maximumFractionDigits: 0 }, language);
    return language === 'ar' ? `${number} ل.س` : `${number} SYP`;
  }
  return new Intl.NumberFormat(localeFor(language), { style: 'currency', currency, maximumFractionDigits: 0 }).format(value);
}

export function formatDate(value: string | number | Date, options: Intl.DateTimeFormatOptions = {}, language: AppLanguage = currentLanguage()): string {
  return new Intl.DateTimeFormat(localeFor(language), options).format(new Date(value));
}

export function formatDateTime(value: string | number | Date, language: AppLanguage = currentLanguage()): string {
  return formatDate(value, { dateStyle: 'medium', timeStyle: 'short' }, language);
}


